function modeFilter(mode,subId){
  return ALL.filter(function(a){
    if(a.obj&&a.obj.indexOf(mode)<0)return false;
    if(!subId)return true;
    if(subId==='food')return a.kind==='food';
    return a.cat===subId;
  });
}

