    h+='<div class="grid2"><div class="field"><label for="n'+b.uid+'">Название по этикетке или ТУ</label><input type="text" id="n'+b.uid+'" data-b="name" data-u="'+b.uid+'" value="'+esc(b.name)+'"></div>';
